rt_combine.py.source:
"""TASK-20260929-594e8d (red team, J3) -- combine the IC-arm and rho-arm Monte
Carlo replicates (independent under the model) into the distribution of the
contract label, by the TEXT rules (outcome_table, success_criterion), assuming
S0 passes, every certificate passes, no halt, no timeout and IR-1, IR-2, IR-6,
IR-7 do not fire. IR-5 is evaluated two ways: 'purposive' (never fires) and
'literal' (fires on every run, because AM3's per_target_cost(L) sums shared and
per-target units). Review computation on synthetic replicates only."""
import json
import sys

ORD, KOB, ZN = "BIN-ORD-19", "BIN-KOB-19", "CTRL-ZN"


# The three axis/label rules, restated from the TEXT (outcome_table) exactly as
# in rt_j3_rules.py (copied here so that importing does not re-run that script).
def h1_text(phi, halted, ic_invalid):
    if ic_invalid:
        return "H1-ARTIFACT"
    if halted.get(ORD) or halted.get(KOB):
        return "H1-INCOMPLETE"
    a, b = phi[ORD], phi[KOB]
    if a == "PASS" and b == "PASS":
        return "H1-POSITIVE"
    if (a == "PASS") != (b == "PASS"):
        return "H1-MIXED"
    if a == "LOW-COV" and b == "LOW-COV":
        return "H1-NEGATIVE-COVERAGE"
    return "H1-NEGATIVE-DEVIANT"


def h2_text(h2, halted, rho_invalid):
    if rho_invalid:
        return "H2-ARTIFACT"
    if halted.get(ORD) or halted.get(KOB):
        return "H2-INCOMPLETE"
    if h2[ZN] and h2[ORD] and h2[KOB]:
        return "H2-POSITIVE"
    if (not h2[ORD]) and (not h2[KOB]):
        return "H2-NEGATIVE"
    return "H2-MIXED"


def label_text(run_valid, h1, h2):
    if not run_valid:
        return "RUN-ARTIFACT"
    if h1 == "H1-POSITIVE" and h2 == "H2-POSITIVE":
        return "POSITIVE"
    if h1 in ("H1-NEGATIVE-COVERAGE", "H1-NEGATIVE-DEVIANT") or h2 == "H2-NEGATIVE":
        return "NEGATIVE"
    return "NOT-VALIDATED"


def load(p):
    return json.load(open(p))


def combine(ic_path, rho_paths, ir5_literal=False):
    ic = load(ic_path)
    rz, ro, rk = (load(p)["per_rep"] for p in rho_paths)
    n = len(ic["per_run"])
    tally, h1t, h2t = {}, {}, {}
    fail_reasons = {}
    for i, run in enumerate(ic["per_run"]):
        z, o, k = rz[i % len(rz)], ro[i % len(ro)], rk[i % len(rk)]
        g1 = run["g1ic"] and (-0.6 <= z["exp"] <= -0.4) and z["inst"]
        if not g1:
            key = "zn_ic:" + ",".join(sorted(run["zn_fail_tests"])) if not run["g1ic"] else "zn_rho"
            fail_reasons[key] = fail_reasons.get(key, 0) + 1
        run_valid = g1 and not ir5_literal
        halted = {ORD: False, KOB: False}
        ic_invalid = (not run["ord_ctl6"]) or (not run["kob_ctl6"]) or (not run["ord_null_disc"])
        phi = {ORD: run["ord_phi"], KOB: run["kob_phi"]}
        h1 = h1_text(phi, halted, ic_invalid)
        rho_invalid = (not o["inst"]) or (not k["inst"])
        h2 = h2_text({ZN: z["h2"], ORD: o["h2"], KOB: k["h2"]}, halted, rho_invalid)
        lab = label_text(run_valid, h1, h2)
        tally[lab] = tally.get(lab, 0) + 1
        if g1:
            h1t[h1] = h1t.get(h1, 0) + 1
            h2t[h2] = h2t.get(h2, 0) + 1
    ng1 = sum(h1t.values())
    return {"n": n, "rule": ic["rule"], "ir5_literal": ir5_literal,
            "contract_label": {k: v / n for k, v in sorted(tally.items(), key=lambda t: -t[1])},
            "H1_axis_given_G1": {k: v / ng1 for k, v in sorted(h1t.items(), key=lambda t: -t[1])} if ng1 else {},
            "H2_axis_given_G1": {k: v / ng1 for k, v in sorted(h2t.items(), key=lambda t: -t[1])} if ng1 else {},
            "G1_fail_reasons": {k: v / n for k, v in sorted(fail_reasons.items(), key=lambda t: -t[1])}}


if __name__ == "__main__":
    rho = ("mc_rho_ZN.json", "mc_rho_ORD.json", "mc_rho_KOB.json")
    out = {}
    for rule in ("uniform", "firstfound"):
        out[rule] = combine(f"mc_ic_{rule}.json", rho)
        out[rule + "_IR5_literal"] = combine(f"mc_ic_{rule}.json", rho, ir5_literal=True)
    print(json.dumps(out, indent=1))

