"""Crude standard-library PDF text extraction (FlateDecode content streams, Tj/TJ
string operands only). Review computation for source checking; lossy by design."""
import re, sys, zlib
data = open(sys.argv[1], 'rb').read()
out = []
for m in re.finditer(rb'stream\r?\n(.*?)\r?\nendstream', data, re.S):
    raw = m.group(1)
    try:
        dec = zlib.decompress(raw)
    except Exception:
        continue
    if b'BT' not in dec:
        continue
    for bt in re.finditer(rb'BT(.*?)ET', dec, re.S):
        seg = bt.group(1)
        line = []
        for tok in re.finditer(rb'\[(.*?)\]\s*TJ|\((.*?)\)\s*Tj|(T\*|Td|TD|\')', seg, re.S):
            if tok.group(1) is not None:
                parts = re.findall(rb'\(((?:\\.|[^\\)])*)\)|(-?\d+\.?\d*)', tok.group(1))
                s = b''
                for txt, num in parts:
                    if txt:
                        s += txt
                    elif num and float(num) < -200:
                        s += b' '
                line.append(s)
            elif tok.group(2) is not None:
                line.append(tok.group(2))
            else:
                line.append(b'\n')
        t = b''.join(line)
        t = re.sub(rb'\\(\d{3})', lambda x: bytes([int(x.group(1), 8)]), t)
        t = t.replace(b'\\(', b'(').replace(b'\\)', b')').replace(b'\\\\', b'\\')
        out.append(t.decode('latin-1'))
sys.stdout.write('\n'.join(out))

